@SpringBootTest(webEnvironment = RANDOM_PORT)
@Testcontainers
class ZadaniaApiEndToEndTest {

    @Container
    static PostgreSQLContainer<?> baza = new PostgreSQLContainer<>("postgres:16");

    @DynamicPropertySource
    static void skonfigurujBaze(DynamicPropertyRegistry registry) {
        registry.add("spring.datasource.url", baza::getJdbcUrl);
        registry.add("spring.datasource.username", baza::getUsername);
        registry.add("spring.datasource.password", baza::getPassword);
    }

    @LocalServerPort
    private int port;

    static RequestSpecification spec;

    @BeforeEach
    void skonfiguruj() {
        RestAssured.port = port;
        spec = new RequestSpecBuilder()
            .setContentType("application/json")
            .addHeader("Authorization", "Bearer " + zdobadzTokenTestowegoUzytkownika())
            .build();
    }
}

@Test
void pelnyCyklZyciaZadania() {
    String noweZadanie = """
        { "tytul": "Nauczyc sie Testcontainers", "wykonane": false }
        """;

    String adresZasobu =
        given().spec(spec).body(noweZadanie)
            .when().post("/api/zadania")
            .then().statusCode(201)
            .extract().header("Location");

    given().spec(spec)
        .when().get(adresZasobu)
        .then().statusCode(200)
            .body("tytul", equalTo("Nauczyc sie Testcontainers"))
            .body("wykonane", equalTo(false));

    String aktualizacja = """
        { "tytul": "Testcontainers OPANOWANE", "wykonane": true }
        """;

    given().spec(spec).body(aktualizacja)
        .when().put(adresZasobu)
        .then().statusCode(200)
            .body("tytul", equalTo("Testcontainers OPANOWANE"));

    given().spec(spec)
        .when().delete(adresZasobu)
        .then().statusCode(204);

    given().spec(spec)
        .when().get(adresZasobu)
        .then().statusCode(404);
}

